  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00053",
          "explanation": "Doctor provided a concrete respectful script for refusal focused on temporary safety rather than coercion.",
          "quote": "先上救护车是保命"
        },
        {
          "event_id": "lite_evt_00119",
          "explanation": "Doctor gave a stepwise strategy for family alignment and involving treating clinicians when the patient wanted to leave.",
          "quote": "家属最好态度一致"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by refusal and family disagreement. The doctor elicited/acknowledged the barrier, assigned roles to family and clinicians, provided fallback ED/120/monitoring pathways, and gave respectful patient-facing language that preserved oxygen and monitoring thresholds.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00119",
          "explanation": "Doctor corrected the misconception that improvement on oxygen meant she was safe to leave.",
          "quote": "不是已经好了"
        },
        {
          "event_id": "lite_evt_00032",
          "explanation": "Doctor corrected the misconception that the usual inhaler could substitute for urgent care.",
          "quote": "不能靠平时吸入药硬扛"
        },
        {
          "event_id": "lite_evt_00134",
          "explanation": "Family restated the corrected plan and accepted the monitored-care path.",
          "quote": "现在暂时同意先不走"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by minimizing because she was awake, wanted to rely on inhalers, and later improved on oxygen. The doctor corrected case-specific misunderstandings in plain Chinese, and the family changed execution by continuing ED monitoring.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00456",
          "explanation": "Doctor actively requested specific document lines rather than guessing from incomplete discharge paperwork.",
          "quote": "逐字读给我哪几行"
        },
        {
          "event_id": "lite_evt_00471",
          "explanation": "Family surfaced document facts including diagnoses and no home oxygen arrangement.",
          "quote": "支气管哮喘、慢性阻塞性肺疾病"
        },
        {
          "event_id": "lite_evt_00477",
          "explanation": "Doctor integrated the obtained document medication facts into the discharge medication plan.",
          "quote": "每天固定早晚吸"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by incomplete records and medication uncertainty. Although the doctor did not use the workspace query, they actively requested and reviewed key document content, identified multiple material facts from the discharge paperwork, and integrated them into medication, home oxygen, follow-up, and red-flag planning.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00004",
          "explanation": "Doctor asked for current oxygen saturation and respiratory function rather than relying only on the prior report.",
          "quote": "此刻血氧、呼吸情况"
        },
        {
          "event_id": "lite_evt_00288",
          "explanation": "Doctor incorporated the verified on-oxygen/with-activity status into the safety plan and prevented unsupervised oxygen changes.",
          "quote": "必须还是由护士医生在监护下试"
        },
        {
          "event_id": "lite_evt_00456",
          "explanation": "Doctor requested specific discharge document data elements to avoid misreading medication and oxygen instructions.",
          "quote": "是否需要家庭氧疗"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by ambiguous SpO2 context, improvement on oxygen, and document uncertainty. The doctor repeatedly sought current/contextual oxygen information, distinguished on-oxygen improvement from true stability, required supervised trials, and requested specific document details before adjusting the plan.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
